'use strict';
const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icon=(name,cls='')=>`<i data-lucide="${name}" class="${cls}"></i>`;
const S={cache:new Map(),renderedKey:null,request:0,previewRequest:0,memberSort:'name',memberOrder:'asc',mobileDay:null,me:null,route:'members',tab:'import',members:[],teams:[],bookings:[],posts:[],week:'',upload:null,uploadName:'',summary:null,viewPost:null};
const slots={vocal:'보컬',guitar1:'기타1',guitar2:'기타2',bass:'베이스',drums:'드럼',keyboard:'키보드'};
const names={schedule:'합주실 예약',notice:'공지',wiki:'무붕 위키',members:'멤버·팀 관리',settings:'예약 설정',guide:'운영진 사용법'};
const today=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Seoul',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
const addDays=(d,n)=>{const a=new Date(d+'T12:00:00Z');a.setUTCDate(a.getUTCDate()+n);return a.toISOString().slice(0,10)};
const sunday=d=>addDays(d,-new Date(d+'T12:00:00Z').getUTCDay());
const fmt=d=>new Intl.DateTimeFormat('ko-KR',{month:'long',day:'numeric'}).format(new Date(d+'T12:00:00Z'));
const postDate=value=>new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Seoul',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date(value));
S.week=sunday(today());
function icons(){window.lucide?.createIcons({attrs:{'stroke-width':1.65}})}
function toast(message){const el=$('#toast');el.textContent=message;el.classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('visible'),3400)}
async function api(path,options={}){
  if(options.raw && options.body instanceof ArrayBuffer && options.body.byteLength>3*1024*1024){
    const bytes=options.body;
    const {token}=await api('/uploads',{method:'POST',body:{path:'/api'+path,size:bytes.byteLength}});
    for(let offset=0;offset<bytes.byteLength;offset+=1024*1024){
      await api('/uploads/'+token+'/'+(offset/(1024*1024)),{method:'PUT',raw:true,body:bytes.slice(offset,offset+1024*1024),headers:{'Content-Type':'application/octet-stream'}});
    }
    options={...options,body:undefined,headers:{...options.headers,'X-Upload-Token':token}};
  }
  const r=await fetch('/api'+path,{credentials:'same-origin',...options,headers:{'Content-Type':'application/json','X-Mooboong-Request':'1',...options.headers},body:options.body!==undefined?(options.raw?options.body:JSON.stringify(options.body)):undefined});const data=await r.json().catch(()=>({error:'서버 응답을 읽을 수 없습니다.'}));if(!r.ok){const error=new Error(typeof data.error==='string'?data.error:data.error?.message||data.message||'요청을 처리하지 못했습니다.');error.status=r.status;if(r.status===401&&S.me){S.request++;S.me=null;S.upload=null;S.members=[];S.teams=[];closeModal();authScreen();toast('다시 로그인해 주세요.')}throw error}if(options.method&&options.method!=='GET')S.cache.clear();return data}
function button(text,action,cls='',ic=''){return `<button type="button" class="btn ${cls}" data-action="${action}">${ic?icon(ic):''}${text}</button>`}
function empty(title,desc,ic='folder-open',action=''){return `<div class="empty">${icon(ic)}<h3>${title}</h3><p>${desc}</p>${action}</div>`}
function field(label,name,attrs='',value='',full=false){return `<div class="field ${full?'full':''}"><label for="${name}">${label}</label><input id="${name}" name="${name}" ${attrs} value="${esc(value)}"></div>`}
function select(label,name,options,value='',full=false){return `<div class="field ${full?'full':''}"><label for="${name}">${label}</label><select id="${name}" name="${name}">${options.map(([v,l])=>`<option value="${esc(v)}" ${String(v)===String(value)?'selected':''}>${esc(l)}</option>`).join('')}</select></div>`}
function showModal(title,body,footer='',wide=false){$('#modal-root').innerHTML=`<div class="modal-overlay"><section class="modal ${wide?'wide':''}" role="dialog" aria-modal="true" aria-labelledby="modal-title"><header class="modal-header"><h2 id="modal-title">${esc(title)}</h2><button class="icon-btn" data-action="close-modal" aria-label="닫기">${icon('x')}</button></header>${body}${footer}</section></div>`;icons();$('.modal input,.modal textarea,.modal select,.modal button')?.focus();document.body.style.overflow='hidden'}
function closeModal(){$('#modal-root').innerHTML='';document.body.style.overflow=''}
function authScreen(setup=false){S.cache.clear();S.renderedKey=null;$('#app').innerHTML=`<div class="auth-layout"><aside class="auth-art"><div class="wordmark">MOOBOONG</div><img class="auth-logo" src="/mooboong-logo.png" alt="무붕 크롬 로고"><div><div class="auth-title">우리의 합주,<br>우리의 <em>공간.</em></div><p>함께 연주하는 시간부터 무붕의 이야기까지.<br>무붕 멤버를 위한 하나의 공간.</p></div><footer>OUR BAND. OUR SPACE. MOOBOONG.</footer></aside><main class="auth-form"><div class="auth-box"><img class="auth-mobile-logo" src="/mooboong-logo.png" alt="무붕 로고"><div class="eyebrow">MOOBOONG MEMBERS</div><h1>${setup?'무붕의 새로운 시작':'다시 만나서 반가워요'}</h1><p>${setup?'첫 운영진 계정을 만들면 준비가 끝나요.<br>멤버와 팀은 엑셀로 한 번에 등록할 수 있어요.':'무붕 계정으로 로그인해 주세요.'}</p><form id="auth-form" data-setup="${setup}">${field('아이디','id','required autocomplete="username" placeholder="아이디를 입력하세요"')}${setup?field('이름','name','required autocomplete="name" placeholder="이름을 입력하세요"'):''}${setup&&S.setupTokenRequired?field('초기 설정 키','setupToken','type="password" required autocomplete="off"'):''}${field('비밀번호','password',`type="password" required autocomplete="${setup?'new-password':'current-password'}" ${setup?'minlength="8"':''} placeholder="${setup?'8자 이상으로 입력하세요':'비밀번호를 입력하세요'}"`)}<div class="inline-error" id="auth-error" role="alert"></div><button class="btn primary" type="submit">${setup?'운영진 계정 만들기':'로그인'} ${icon('arrow-right')}</button></form><div class="auth-footer">${setup?'이 계정은 멤버와 팀, 예약 규칙을 관리할 수 있어요.':'처음 로그인하나요? 운영진에게 아이디를 확인해 주세요.'}</div></div></main></div>`;icons()}
function passwordScreen(){showModal('새 비밀번호를 설정해 주세요',`<p>비밀번호를 새로 설정해 주세요.<br>본인만 아는 비밀번호로 바꾸면 무붕 공간을 이용할 수 있어요.</p><form id="password-form" style="margin-top:24px">${field('현재 비밀번호','currentPassword','type="password" autocomplete="current-password" required')}${field('새 비밀번호','newPassword','type="password" autocomplete="new-password" minlength="8" required')}${field('새 비밀번호 확인','confirmPassword','type="password" autocomplete="new-password" minlength="8" required')}<button type="button" class="btn small" data-action="logout">로그아웃</button><div id="password-error" class="inline-error" role="alert"></div><div class="modal-actions"><button type="submit" class="btn primary">비밀번호 변경</button></div></form>`);if(S.me.mustChangePassword)$('.modal-header button')?.remove()}
function shell(){const admin=!!S.me.admin;$('#app').innerHTML=`<div class="shell"><aside class="sidebar"><button class="mobile-close" data-action="toggle-nav" aria-label="메뉴 닫기">${icon('x')}</button><a class="brand" href="#schedule"><div class="brand-logo"><img src="/mooboong-logo.png" alt="무붕 로고"></div><small>MOOBOONG / BAND CLUB</small></a><div class="nav-label">WORKSPACE</div>${[['schedule','calendar-days'],['notice','megaphone'],['wiki','book-open']].map(([r,i])=>`<a class="nav-item ${S.route===r?'active':''}" href="#${r}">${icon(i)}${names[r]}</a>`).join('')}${admin?`<div class="nav-label">MANAGEMENT</div>${[['members','users'],['settings','sliders-horizontal'],['guide','notebook-tabs']].map(([r,i])=>`<a class="nav-item ${S.route===r?'active':''}" href="#${r}">${icon(i)}${names[r]}</a>`).join('')}`:''}<div class="sidebar-bottom"><div class="club-note"><strong>오늘도 좋은 합주를.</strong>연습이 끝나면 장비와 공간을<br>다음 멤버를 위해 정리해 주세요.</div><div class="profile"><div class="avatar">${esc(S.me.name?.slice(0,1))}</div><div><div class="name">${esc(S.me.name)}</div><small>${admin?'운영진':'무붕 멤버'}</small></div><button data-action="logout" aria-label="로그아웃" title="로그아웃">${icon('log-out')}</button></div></div></aside><div class="workspace"><header class="topbar"><div class="crumb"><button class="icon-btn mobile-toggle" data-action="toggle-nav" aria-label="메뉴 열기">${icon('menu')}</button><img class="mobile-logo" src="/mooboong-logo.png" alt="무붕 로고"><span>무붕</span>${icon('chevron-right')}<strong>${names[S.route]}</strong></div><div class="top-meta"><span>${today().replaceAll('-','. ')}</span><span class="tag ${admin?'orange':''}">${admin?'운영진 공간':'멤버 공간'}</span><button type="button" class="icon-btn" data-action="reload" aria-label="최신 정보 새로고침" title="최신 정보 새로고침">${icon('refresh-cw')}</button><button type="button" class="btn small top-logout" data-action="logout">${icon('log-out')}로그아웃</button></div></header><div class="route-sync" id="route-sync" role="status" hidden>최신 내용 확인 중</div><main class="content" id="main"><div class="skeleton" role="status">화면을 준비하고 있어요…</div></main></div></div>`;icons()}
function pageHead(eyebrow,title,desc,actions=''){return `<div class="page-head"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${desc}</p></div>${actions?`<div class="head-actions">${actions}</div>`:''}</div>`}
function stat(label,value,unit,ic,accent=false){return `<div class="stat"><div><div class="stat-label">${label}</div><div class="stat-value">${value}<span>${unit}</span></div></div><div class="stat-icon ${accent?'accent':''}">${icon(ic)}</div></div>`}
function renderRoute(route,data){Object.assign(S,data);if(route==='members')renderMembers();else if(route==='schedule')renderSchedule();else if(route==='guide')renderGuide();else if(route==='settings')renderSettings();else renderPosts()}
async function navigate(){
  if(!S.me)return;
  const request=++S.request;
  let route=location.hash.slice(1).split('/')[0]||(S.me.admin?'members':'schedule');
  if(!names[route]||(!S.me.admin&&['members','settings','guide'].includes(route)))route='schedule';
  const week=S.week,key=route==='schedule'?route+':'+week:route;
  const same=S.renderedKey===key&&!!$('#main');
  S.route=route;S.viewPost=null;
  if(!same)shell();
  if(S.me.mustChangePassword){$('#main').innerHTML='<div class="panel skeleton">비밀번호를 변경하면 무붕 공간을 이용할 수 있어요.</div>';return}
  const cached=S.cache.get(key);
  if(cached&&!same){renderRoute(route,cached);S.renderedKey=key}
  const visible=same||!!cached;
  const indicator=setTimeout(()=>{if(request===S.request&&$('#route-sync'))$('#route-sync').hidden=false},350);
  try{
    let data;
    if(route==='members'){const [m,t]=await Promise.all([api('/members'),api('/teams')]);data={members:m.members,teams:t.teams}}
    else if(route==='schedule'){const b=await api('/schedule?week='+week);data={bookingData:b,bookings:b.bookings,teams:b.teams}}
    else if(route==='guide')data={guideSections:(await api('/admin-guide')).sections};
    else if(route==='settings')data={settings:(await api('/settings')).settings};
    else data={posts:(await api('/posts?kind='+route)).posts.filter(p=>p.kind===route)};
    if(!S.me||request!==S.request)return;
    // Keep only a small in-memory history; it is cleared on logout and mutations.
    S.cache.delete(key);S.cache.set(key,data);if(S.cache.size>12)S.cache.delete(S.cache.keys().next().value);
    if(cached&&S.renderedKey===key&&JSON.stringify(cached)===JSON.stringify(data))return;
    const search=route==='members'&&same?$('#member-search')?.value:undefined;
    renderRoute(route,data);S.renderedKey=key;
    if(search&&$('#member-search')){$('#member-search').value=search;refreshMemberTable()}
  }catch(e){
    if(!S.me||request!==S.request)return;
    if(visible)toast('최신 정보를 가져오지 못했습니다. 상단 새로고침을 눌러 주세요.');
    else $('#main').innerHTML=`<div class="panel page-error">${esc(e.message)}<br><br>${button('다시 불러오기','reload','','rotate-cw')}</div>`;
  }finally{clearTimeout(indicator);if(request===S.request&&$('#route-sync'))$('#route-sync').hidden=true}
}

function renderMembers(){const adminCount=S.members.filter(m=>m.admin).length;$('#main').innerHTML=pageHead('MEMBERS & TEAMS','함께 만드는 무붕','멤버와 팀 정보를 한곳에서 관리하세요.',`<a class="btn" href="/templates/mooboong-import.xlsx" download>${icon('download')}엑셀 양식</a>${button('전체 멤버 내려받기','export-members','','file-spreadsheet')}${button('엑셀 일괄 등록','import-tab','primary','plus')}`)+`<div class="stats">${stat('전체 멤버',S.members.length,'명','users',true)}${stat('등록된 팀',S.teams.length,'팀','audio-lines')}${stat('운영진',adminCount,'명','shield-check')}</div><section class="panel"><nav class="tabs" aria-label="관리 화면"><button class="tab ${S.tab==='members'?'active':''}" data-action="members-tab">멤버 목록 <span class="count">${S.members.length}</span></button><button class="tab ${S.tab==='teams'?'active':''}" data-action="teams-tab">팀 목록 <span class="count">${S.teams.length}</span></button><button class="tab ${S.tab==='import'?'active':''}" data-action="import-tab">${icon('upload')}엑셀 일괄 등록</button></nav><div class="panel-body" id="member-body">${S.tab==='import'?importContent():S.tab==='members'?membersContent():teamsContent()}</div></section><div class="helper-foot">${icon('lock-keyhole')}멤버의 연락처와 등록 정보는 운영진에게만 표시됩니다.</div>`;icons();bindDropzone()}
function membersContent(){return `<div class="toolbar"><div class="search">${icon('search')}<input id="member-search" aria-label="멤버 검색" placeholder="이름, 아이디, 기수로 검색"></div><div class="sort-controls"><select id="member-sort" aria-label="멤버 정렬 기준">${[['name','이름순'],['generation','기수순'],['session','세션순']].map(([v,l])=>`<option value="${v}" ${S.memberSort===v?'selected':''}>${l}</option>`).join('')}</select><select id="member-order" aria-label="정렬 방향"><option value="asc" ${S.memberOrder==='asc'?'selected':''}>오름차순</option><option value="desc" ${S.memberOrder==='desc'?'selected':''}>내림차순</option></select></div></div><div id="members-table">${memberTable(sortedMembers(S.members))}</div>`}
function memberTable(list){return list.length?`<div class="table-scroll"><table><thead><tr><th>멤버</th><th>세션</th><th>기수</th><th>소속 팀</th><th>전화번호</th><th>권한</th><th>비밀번호 관리</th></tr></thead><tbody>${list.map(m=>`<tr><td><div class="member-cell"><span class="avatar">${esc(m.name.slice(0,1))}</span><div><strong>${esc(m.name)}</strong><small>${esc(m.id)}</small></div></div></td><td>${esc(m.session)||'—'}</td><td>${esc(m.generation)||'—'}</td><td>${m.teams?.map(t=>esc(t.name)).join(', ')||'—'}</td><td>${esc(m.phone)||'—'}</td><td><span class="tag ${m.admin?'orange':''}">${m.admin?'운영진':'멤버'}</span></td><td><div class="password-actions"><span class="tag ${m.mustChangePassword?'orange':''}">${m.mustChangePassword?'변경 필요':'설정 완료'}</span><button type="button" class="btn small" data-action="member-password" data-id="${esc(m.id)}">${m.id===S.me.id?'내 비밀번호 변경':'재설정'}</button></div></td></tr>`).join('')}</tbody></table></div>`:empty('등록된 멤버가 없어요','엑셀에 멤버 정보를 입력하고 한 번에 등록해 보세요.','users',button('엑셀 등록하기','import-tab','primary','upload'))}
function temporaryPassword(){const bytes=crypto.getRandomValues(new Uint8Array(18));return Array.from(bytes,b=>b.toString(16).padStart(2,'0')).join('')}
function memberPasswordModal(id){
  const member=S.members.find(m=>m.id===id);if(!member)return;
  if(id===S.me.id){passwordScreen();return}
  showModal('멤버 비밀번호 재설정',`<p><strong>${esc(member.name)}</strong> · ${esc(member.id)}</p><p class="password-help">현재 비밀번호는 조회할 수 없습니다. 새 임시 비밀번호를 멤버에게 전달해 주세요. 저장하면 기존 로그인은 해제되고, 다음 로그인 시 비밀번호 변경이 필요합니다.</p><form id="member-password-form" data-id="${esc(id)}">${field('새 임시 비밀번호','newPassword','type="password" required minlength="8" maxlength="128" autocomplete="off"',temporaryPassword())}<div class="password-tools">${button('보기','toggle-temp-password','small','eye')}${button('자동 생성','generate-temp-password','small','refresh-cw')}${button('복사','copy-temp-password','small','copy')}</div>${field('운영진 본인의 현재 비밀번호','operatorPassword','type="password" required maxlength="128" autocomplete="current-password"')}<div class="inline-error" role="alert"></div><div class="modal-actions">${button('취소','close-modal')}<button type="submit" class="btn primary">임시 비밀번호 저장</button></div></form>`);
}
function teamsContent(){return S.teams.length?`<div class="section-title"><div><h2>무붕의 팀</h2><p>파트별 멤버와 공석을 확인하세요.</p></div><span class="tag">${S.teams.length}팀</span></div><div class="team-grid">${[...S.teams].sort((a,b)=>a.name.localeCompare(b.name,'ko',{numeric:true})).map(t=>`<article class="team-card"><header><h3>${esc(t.name)}</h3><span class="tag">${t.members?.length||0}명</span></header><div class="team-slots">${Object.entries(slots).map(([key,label])=>{const member=t.members?.find(m=>m.slot===key);return `<div class="team-slot"><small>${label}</small><span class="${member?'':'vacant'}">${member?esc(member.name):'공석'}</span></div>`}).join('')}</div></article>`).join('')}</div>`:empty('첫 번째 팀을 등록해 주세요','보컬부터 키보드까지, 공석은 비워 두어도 괜찮아요.','audio-lines',button('엑셀 등록하기','import-tab','primary','upload'))}
function importContent(){if(S.summary)return `<div class="success-panel"><div class="success-icon">${icon('check')}</div><h2>등록이 완료됐어요</h2><p>멤버와 팀 정보를 반영했습니다.</p><div class="upload-summary" style="justify-content:center">${summaryItems(S.summary)}</div>${button('멤버 목록 보기','members-tab','primary','users')} ${button('다른 파일 등록','reset-upload','','upload')}</div>`;if(S.upload)return reviewContent();return `<div class="section-title"><div><h2>엑셀 하나로, 한 번에.</h2><p>작성한 파일을 올리면 등록 전에 변경 내용을 확인할 수 있어요.</p></div></div><div class="steps"><span class="step active"><b>1</b>파일 업로드</span><span class="step-line"></span><span class="step"><b>2</b>내용 검토</span><span class="step-line"></span><span class="step"><b>3</b>등록 완료</span></div><div class="upload-grid"><label class="dropzone" id="dropzone" tabindex="0" role="button" aria-label="엑셀 파일 선택"><input class="visually-hidden" type="file" id="xlsx-file" accept=".xlsx"><span class="drop-icon">${icon('cloud-upload')}</span><h3>엑셀 파일을 여기에 놓아 주세요</h3><p>또는 아래 버튼으로 파일을 선택하세요.</p><span class="btn">파일 선택 ${icon('arrow-up-right')}</span><span class="file-note">XLSX 파일 · 최대 4MB</span></label><div class="template-card">${icon('file-spreadsheet')}<h3>처음 등록하시나요?</h3><p>무붕 전용 양식을 내려받아<br>멤버와 팀 시트를 작성해 주세요.</p><a href="/templates/mooboong-import.xlsx" class="btn" download>${icon('download')}엑셀 양식 다운로드</a></div></div><div class="info-strip">${icon('info')}<div>같은 아이디는 기존 정보를 수정합니다. 파일에 없는 멤버와 팀은 그대로 유지돼요.<br>멤버 시트의 팀 칸은 비워 두세요. 팀 시트를 등록하면 소속 팀이 자동으로 채워집니다.<br>아이디 기본값은 이름, 신규 비밀번호 기본값은 20000000입니다.</div></div><div class="format-guide"><h3>이렇게 작성해 주세요</h3><div class="format-row"><strong>멤버 시트</strong><div>${['아이디','이름','비밀번호','세션','기수','전화번호','팀','관리자여부'].map(t=>`<code>${t}</code>`).join('')}</div></div><div class="format-row"><strong>팀 시트</strong><div>${['팀명','보컬','기타1','기타2','베이스','드럼','키보드'].map(t=>`<code>${t}</code>`).join('')}</div></div></div>`}
function summaryItems(s){return `<span>신규 멤버 <strong>${s.newMembers??0}</strong></span><span>멤버 수정 <strong>${s.updatedMembers??0}</strong></span><span>신규 팀 <strong>${s.newTeams??0}</strong></span><span>팀 수정 <strong>${s.updatedTeams??0}</strong></span>`}
function reviewContent(){const p=S.upload.preview;return `<div class="steps"><span class="step"><b>✓</b>파일 업로드</span><span class="step-line"></span><span class="step active"><b>2</b>내용 검토</span><span class="step-line"></span><span class="step"><b>3</b>등록 완료</span></div><div class="review-head"><h3>${icon('file-spreadsheet')} ${esc(S.uploadName)}</h3>${button('다른 파일 선택','reset-upload','small','rotate-ccw')}</div><div class="upload-summary">${summaryItems(p.summary)}</div>${p.errors?.length?`<div class="error-box"><strong>아래 ${p.errors.length}개 항목을 수정한 뒤 다시 업로드해 주세요.</strong><ul>${p.errors.map(e=>`<li>${esc(e.sheet)} ${e.row?e.row+'행':''}${e.column?' · '+esc(e.column):''}: ${esc(e.message)}</li>`).join('')}</ul></div>`:''}${p.warnings?.length?`<div class="info-strip" style="margin-bottom:20px">${icon('info')}<div>${p.warnings.map(w=>`${esc(w.sheet)} ${w.row?w.row+'행':''}: ${esc(w.message)}`).join('<br>')}</div></div>`:''}<div class="table-scroll"><table><thead><tr><th>구분</th><th>아이디 / 팀명</th><th>이름 / 구성</th><th>세션 · 기수</th><th>전화번호</th><th>소속 팀</th><th>권한 / 비밀번호</th></tr></thead><tbody>${p.members.map(m=>`<tr><td><span class="tag ${m.action==='create'?'green':'blue'}">${m.action==='create'?'신규 멤버':'멤버 수정'}</span></td><td>${esc(m.id)}</td><td>${esc(m.name)}</td><td>${esc(m.session)||'—'} · ${esc(m.generation)||'—'}</td><td>${esc(m.phone)||'—'}</td><td>${(m.teams||[]).map(esc).join(', ')||'—'}</td><td>${m.admin?'운영진':'멤버'} · ${esc(({default:'기본 비밀번호',keep:'기존 유지',set:'변경',preserve:'기존 유지'})[m.passwordAction]||m.passwordAction||'')}</td></tr>`).join('')}${p.teams.map(t=>`<tr><td><span class="tag ${t.action==='create'?'green':'blue'}">${t.action==='create'?'신규 팀':'팀 수정'}</span></td><td>${esc(t.name)}</td><td colspan="5">${Object.entries(slots).map(([k,l])=>`${l}: ${esc(t.slots?.[k])||'공석'}`).join(' · ')}</td></tr>`).join('')}</tbody></table></div>${p.membershipChanges?.length?`<div class="info-strip"><div><strong>소속 팀 자동 반영</strong><br>${p.membershipChanges.map(m=>`${esc(m.name)}: ${m.before.map(esc).join(', ')||'소속 없음'} → ${m.after.map(esc).join(', ')||'소속 없음'}`).join('<br>')}</div></div>`:''}<div class="review-actions">${button('취소','reset-upload')}${button('일괄 등록','commit-upload','primary','check').replace('<button','<button '+(!p.valid?'disabled':''))}</div>`}
function bindDropzone(){const z=$('#dropzone');if(!z)return;z.addEventListener('dragover',e=>{e.preventDefault();z.classList.add('dragover')});z.addEventListener('dragleave',()=>z.classList.remove('dragover'));z.addEventListener('drop',e=>{e.preventDefault();z.classList.remove('dragover');if(e.dataTransfer.files[0])uploadFile(e.dataTransfer.files[0])});z.addEventListener('keydown',e=>{if(['Enter',' '].includes(e.key)){e.preventDefault();$('#xlsx-file').click()}})}
async function uploadFile(file){if(!file.name.toLowerCase().endsWith('.xlsx'))return toast('XLSX 형식의 엑셀 파일을 선택해 주세요.');if(file.size>4*1024*1024)return toast('4MB 이하의 파일을 선택해 주세요.');$('#member-body').innerHTML=`<div class="skeleton">${icon('file-spreadsheet')}<p style="margin-top:16px">파일의 멤버와 팀 정보를 검토하고 있어요.</p></div>`;icons();try{const result=await api('/import/file',{method:'POST',body:await file.arrayBuffer(),raw:true,headers:{'Content-Type':'application/octet-stream','X-Filename':encodeURIComponent(file.name)}});S.upload=result;S.uploadName=file.name;S.summary=null;renderMembers()}catch(e){S.upload=null;renderMembers();toast(e.message)}}
const minutes=t=>Number(t.slice(0,2))*60+Number(t.slice(3,5));
function bookingDetail(id){const b=S.bookings.find(x=>String(x.id)===String(id));if(!b)return;if(b.type==='event'){eventDetail(b);return}showModal(b.type==='team'?'팀 합주 예약':'개인 연습 예약',`<dl class="details-list"><dt>예약자</dt><dd>${esc(b.createdByName||b.memberName)}</dd>${b.memberId!==b.createdBy?`<dt>이용 멤버</dt><dd>${esc(b.memberName)}</dd>`:''}${b.type==='team'?`<dt>팀</dt><dd>${esc(b.teamName)}</dd>`:''}<dt>날짜</dt><dd>${b.date}</dd><dt>시간</dt><dd>${b.start} – ${b.end}</dd></dl>`,`<div class="modal-actions">${b.canCancel?`<button class="btn danger" data-action="cancel-booking" data-id="${b.id}">${b.seriesId?'이 날짜만 취소':'예약 취소'}</button>`:''}${b.seriesId&&(b.canCancel||S.me.admin)?`<button class="btn danger" data-action="cancel-series" data-id="${b.id}">반복 예약 전체 취소</button>`:''}${button('닫기','close-modal')}</div>`)}

async function downloadMembers(el){
  el.disabled=true;
  try{
    const response=await fetch('/api/members/export?'+new URLSearchParams({sort:S.memberSort,order:S.memberOrder}),{credentials:'same-origin',cache:'no-store'});
    if(!response.ok){const error=await response.json().catch(()=>({}));throw new Error(error.error||'엑셀 다운로드에 실패했습니다.')}
    const blob=await response.blob();if(!S.me?.admin)return;
    const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`mooboong-members-${today()}.xlsx`;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),10000);
    toast('전체 멤버·팀 엑셀을 내려받았습니다. 비밀번호 칸은 비워 두었습니다.');
  }finally{el.disabled=false}
}
function eventDetail(event){
  showModal('커스텀 일정',`<div class="event-heading"><span class="tag event">합주실 사용 제한</span><h3>${esc(event.title)}</h3></div><dl class="details-list"><dt>날짜</dt><dd>${event.date}</dd><dt>시간</dt><dd>${event.start} – ${event.end}</dd><dt>등록자</dt><dd>${esc(event.createdByName)}</dd></dl>${event.description?`<div class="event-description">${linkedText(event.description)}</div>`:''}<p class="event-help">이 시간에는 개인 연습·팀 합주를 예약할 수 없어요.</p>`,`<div class="modal-actions">${S.me.admin?`<button class="btn" data-action="edit-event" data-id="${event.id}">${icon('pencil')}수정</button><button class="btn danger" data-action="delete-event" data-id="${event.eventId}">일정 삭제</button>`:''}${button('닫기','close-modal')}</div>`);
}
function eventModal(event=null){
  if(!S.me?.admin)return;
  const date=event?.date||(S.week>today()?S.week:today());
  const options=Array.from({length:33},(_,i)=>{const mins=480+i*30,t=String(Math.floor(mins/60)).padStart(2,'0')+':'+String(mins%60).padStart(2,'0');return [t,t]});
  showModal(event?'커스텀 일정 수정':'커스텀 일정 추가',`<form id="event-form" data-id="${event?.eventId||''}"><details class="booking-week" open><summary>선택한 주의 전체 시간표</summary><div id="booking-week-preview"></div></details><div class="form-grid">${field('일정 제목','title','required maxlength="100" placeholder="예: 합주실 대청소, 신입 부원 면접"',event?.title||'',true)}${field('날짜','event-date',`type="date" required min="${today()}" max="${addDays(today(),366)}"`,date,true)}${select('시작 시간','start',options.slice(0,-1),event?.start||'18:00')}${select('종료 시간','end',options.slice(1),event?.end||'20:00')}<div class="field full"><label for="description">설명 (선택)</label><textarea id="description" name="description" maxlength="2000" placeholder="준비물이나 안내할 내용을 입력해 주세요.">${esc(event?.description||'')}</textarea></div></div><div class="info-strip">${icon('info')}운영진만 관리할 수 있어요. 해당 시간의 예약을 막으며 개인·팀 연습 한도에는 포함되지 않습니다. 08:00–24:00 전체를 선택하면 하루를 비워둘 수 있어요.</div><div class="inline-error" role="alert"></div><div class="modal-actions">${button('취소','close-modal')}<button class="btn primary" type="submit">${event?'변경 저장':'일정 추가'}</button></div></form>`,'',true);
  updateBookingPreview(date);
}
function renderPosts(){const wiki=S.route==='wiki';$('#main').innerHTML=pageHead(wiki?'MOOBOONG WIKI':'NOTICE',wiki?'무붕의 모든 노하우':'무붕 소식',wiki?'장비 사용법부터 동아리 생활까지, 함께 쌓아 가는 기록.':'함께 알아야 할 이야기들을 모았습니다.',S.me.admin?(wiki?button('노션 가져오기','notion-import','','file-up'):'')+button(wiki?'문서 작성':'공지 작성','new-post','primary','plus'):'')+`<div class="toolbar"><div class="search">${icon('search')}<input id="post-search" aria-label="${wiki?'위키':'공지'} 검색" placeholder="${wiki?'찾고 싶은 문서를 검색하세요':'공지 제목이나 내용을 검색하세요'}"></div><span class="tag">전체 ${S.posts.length}${wiki?'개 문서':'개 공지'}</span></div><div id="post-list">${postCards(S.posts)}</div>`;icons()}
function postCards(posts){return posts.length?`<div class="posts-grid">${posts.sort((a,b)=>Number(b.pinned)-Number(a.pinned)||b.id-a.id).map(p=>`<button class="post-card" data-action="read-post" data-id="${p.id}"><span class="tag ${p.pinned?'orange':''}">${p.pinned?'중요 · ':''}${esc(p.category||'일반')}</span><h3>${esc(p.title)}</h3><p>${esc(p.body)}</p><footer>${esc(p.authorName)} · ${postDate(p.updatedAt||p.createdAt)}</footer></button>`).join('')}</div>`:`<section class="panel">${empty(S.route==='wiki'?'첫 번째 문서를 기다리고 있어요':'아직 등록된 공지가 없어요',S.me.admin?(S.route==='wiki'?'합주실 이용법이나 장비 사용법을 남겨 보세요.':'멤버들에게 전할 첫 소식을 작성해 보세요.'):'새로운 내용이 등록되면 이곳에서 확인할 수 있어요.',S.route==='wiki'?'book-open':'megaphone',S.me.admin?button('작성하기','new-post','primary','plus'):'')}</section>`}
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!S.me?.mustChangePassword)closeModal();if(e.key==='Tab'&&$('.modal')){const focusable=$$('button:not([disabled]),input:not([disabled]),select,textarea,a[href]',$('.modal')).filter(el=>el.offsetParent!==null);if(!focusable.length)return;const first=focusable[0],last=focusable.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}});
window.addEventListener('hashchange',()=>{if(S.me&&!S.me.mustChangePassword)navigate()});
async function boot(){try{const status=await api('/status');S.setupTokenRequired=status.setupTokenRequired;if(status.setupRequired){authScreen(true);return}try{S.me=(await api('/me')).member}catch{authScreen();return}await navigate();if(S.me.mustChangePassword||S.me.must_change_password)passwordScreen()}catch(e){$('#app').innerHTML=`<div class="loading-screen" style="font-size:20px">연결을 확인해 주세요<span>${esc(e.message)}</span><button class="btn" data-action="reload-page" style="margin-top:20px">다시 시도</button></div>`}}
boot();

matchMedia('(max-width:600px)').addEventListener('change',()=>{if(S.me&&S.route==='schedule'&&S.bookingData)renderSchedule()});

function sortedMembers(list){return [...list].sort((a,b)=>{const key=S.memberSort||'name',order=S.memberOrder==='desc'?-1:1;return order*(String(a[key]||'').localeCompare(String(b[key]||''),'ko',{numeric:true})||a.name.localeCompare(b.name,'ko')||a.id.localeCompare(b.id,'ko'))})}
function refreshMemberTable(){const q=($('#member-search')?.value||'').toLowerCase();$('#members-table').innerHTML=memberTable(sortedMembers(S.members.filter(m=>[m.name,m.id,m.generation,m.session].some(v=>String(v||'').toLowerCase().includes(q)))));icons()}
function linkedText(value){return String(value||'').split(/(https?:\/\/[^\s<>"']+)/g).map((part,i)=>{if(i%2===0)return esc(part);const url=part.replace(/[.,!?;)]+$/,'');return `<a href="${esc(url)}" target="_blank" rel="noopener noreferrer">${esc(url)}</a>${esc(part.slice(url.length))}`}).join('')}
function weeklyGrid(bookings,week,preview=false){const now=today();return `<div class="calendar-grid ${preview?'preview-grid':''}"><div class="day-head"></div>${Array.from({length:7},(_,i)=>{const d=addDays(week,i);return `<div class="day-head ${d===now?'today':''}">${['일','월','화','수','목','금','토'][i]}<strong>${Number(d.slice(-2))}</strong></div>`}).join('')}${Array.from({length:32},(_,row)=>{const mins=480+row*30,time=String(Math.floor(mins/60)).padStart(2,'0')+':'+String(mins%60).padStart(2,'0');return `<div class="time-label">${row%2===0?time:''}</div>${Array.from({length:7},(_,day)=>{const date=addDays(week,day),bk=bookings.find(x=>x.date===date&&minutes(x.start)<=mins&&minutes(x.end)>mins),starts=bk?.start===time;return `<button type="button" class="time-cell ${bk?'occupied':''}" data-action="${preview?'pick-preview-slot':'calendar-slot'}" data-date="${date}" data-time="${time}" ${bk&&!preview?`data-booking="${bk.id}"`:''} ${bk&&preview?'disabled':''} aria-label="${date} ${time} ${bk?esc(bk.title||bk.teamName||bk.memberName)+' 예약됨':'예약 가능'}">${starts?`<span class="booking-block ${bk.type==='event'?'event':bk.type==='team'?'team':''}" style="height:${(minutes(bk.end)-minutes(bk.start))/30*(preview?23:38)-4}px"><strong>${esc(bk.title||bk.teamName||bk.memberName)}</strong><span class="booking-creator">${bk.type==='event'?'등록':'예약'}: ${esc(bk.createdByName||bk.memberName)}</span><span>${bk.start}–${bk.end}</span>${bk.seriesId?'<span class="repeat-mark">↻</span>':''}</span>`:''}</button>`}).join('')}`}).join('')}</div>`}
function renderSchedule(){const b=S.bookingData,usage=b.usage?.personalHours||0,limit=b.settings.personalWeeklyHours,own=S.bookings.filter(x=>x.memberId===S.me.id);$('#main').innerHTML=pageHead('REHEARSAL / 08:00—24:00','우리의 다음 합주','이번 주의 빈 시간을 보고, 함께 연주할 시간을 골라 주세요.',(S.me.admin?button('커스텀 일정','new-event','','calendar-plus'):'')+button('예약하기','new-booking','primary','plus'))+`<div class="quota-strip"><div class="quota-pill"><span>내 개인 연습</span><strong>${usage}<small> / ${limit}시간</small></strong></div>${(b.usage?.teams||[]).map(t=>`<div class="quota-pill team"><span>${esc(t.teamName)} 합주</span><strong>${t.hours}<small> / ${b.settings.teamWeeklyHours}시간</small></strong></div>`).join('')}${!(b.usage?.teams||[]).length?`<div class="quota-pill team"><span>팀 합주 한도</span><strong>${b.settings.teamWeeklyHours}<small>시간 / 주</small></strong></div>`:''}</div><div class="reserve-layout"><section class="panel"><div class="calendar-tools"><div class="calendar-period"><button class="icon-btn" data-action="prev-week" aria-label="지난주">${icon('chevron-left')}</button><span>${fmt(S.week)} — ${fmt(addDays(S.week,6))}</span><button class="icon-btn" data-action="next-week" aria-label="다음 주">${icon('chevron-right')}</button>${button('이번 주','today-week','small')}</div><div class="legend"><span><i></i>개인</span><span><i class="team"></i>팀</span><span><i class="event"></i>일정</span>${button('넓게 보기','zoom-calendar','small')}</div></div><div class="calendar" id="main-calendar">${weeklyGrid(S.bookings,S.week)}</div><div class="calendar-note">08:00–24:00 · 30분 단위 · ${b.settings.blockSameDayCancellation?'예약 당일 취소는 운영진에게 문의해 주세요.':'시작 전에는 본인·소속 팀 예약을 취소할 수 있어요.'}</div></section><aside class="aside-card"><h3>이번 주 내 예약 <span class="tag">${own.length}</span></h3>${own.length?own.map(x=>`<button class="mini-booking" data-booking="${x.id}"><strong>${fmt(x.date)} · ${x.start}–${x.end}</strong><span>${x.teamName?esc(x.teamName):'개인 연습'}${x.seriesId?' · 매주 반복':''}</span><span>예약자: ${esc(x.createdByName||x.memberName)}</span></button>`).join(''):'<p>예약된 시간이 없어요.<br>시간표의 빈 칸을 눌러 보세요.</p>'}<div class="info-strip">연속 최대 ${b.settings.maxContinuousHours}시간<br>${b.settings.advanceWeeks}주 앞까지 예약 가능${b.settings.recurringUntil?`<br>정기예약 마감 ${b.settings.recurringUntil}`:''}</div></aside></div>`;icons()}
async function updateBookingPreview(date){
  const key=++S.previewRequest,week=sunday(date);
  const render=data=>{if(!$('#booking-week-preview')||key!==S.previewRequest)return;$('#booking-week-preview').innerHTML=`<div class="preview-caption">${fmt(data.week)} — ${fmt(addDays(data.week,6))} · 빈 칸을 눌러 선택</div><div class="booking-calendar">${weeklyGrid(data.bookings,data.week,true)}</div>`;icons()};
  const cached=S.cache.get('schedule:'+week)?.bookingData||(S.bookingData?.week===week?S.bookingData:null);
  if(cached)render(cached);
  try{render(await api('/bookings?week='+week))}catch(e){if($('#booking-week-preview')&&key===S.previewRequest){if(cached)toast('시간표 갱신에 실패했습니다. 예약 시 중복 여부를 다시 확인합니다.');else $('#booking-week-preview').textContent=e.message}}
}

async function bookingModal(date=today(),time='18:00'){const memberTeams=S.me.admin?S.teams:S.teams.filter(t=>t.members?.some(m=>m.id===S.me.id));let members=[];if(S.me.admin)members=[...(S.bookingData?.bookingMembers||(await api('/booking-options')).members)].sort((a,b)=>a.name.localeCompare(b.name,'ko',{numeric:true}));if(!S.me)return;const options=Array.from({length:33},(_,i)=>{let m=480+30*i,t=String(Math.floor(m/60)).padStart(2,'0')+':'+String(m%60).padStart(2,'0');return [t,t]});showModal('합주실 예약',`<form id="booking-form"><details class="booking-week" open><summary>선택한 주의 전체 시간표</summary><div id="booking-week-preview"></div></details><div class="form-grid">${select('예약 종류','type',[['personal','개인 연습'],['team','팀 합주']],'personal',true)}${S.me.admin?`<div class="field full" id="booking-member-field"><label for="bookingMemberId">개인 연습 예약 대상</label><select id="bookingMemberId" name="memberId" required>${members.map(m=>`<option value="${esc(m.id)}" ${m.id===S.me.id?'selected':''}>${esc(m.name)} · ${esc(m.id)}${m.id===S.me.id?' (나)':''}</option>`).join('')}</select><small>선택한 멤버의 예약으로 등록되며 해당 멤버의 시간 한도를 적용합니다.</small></div>`:''}${field('날짜','date',`type="date" required min="${today()}"`,date,true)}${select('시작 시간','start',options.slice(0,-1),time)}${select('종료 시간','end',options.slice(1),options[Math.min(32,options.findIndex(([t])=>t===time)+2)]?.[0]||'24:00')}<div class="field full" id="team-field" hidden><label for="teamId">팀 선택</label><select id="teamId" name="teamId"><option value="">팀을 선택하세요</option>${memberTeams.map(t=>`<option value="${t.id}">${esc(t.name)}</option>`).join('')}</select><label class="check-field"><input type="checkbox" id="repeat-weekly">같은 요일·시간으로 매주 반복</label><div id="repeat-end-field" hidden><label for="repeatUntil">마지막 예약 날짜 (해당 날짜 포함)</label><input id="repeatUntil" name="repeatUntil" type="date" min="${date}" max="${S.bookingData?.settings.recurringUntil||addDays(today(),366)}" disabled></div></div></div><div class="info-strip">${icon('info')}${S.me.admin?'운영진은 모든 멤버의 개인 연습과 모든 팀의 합주를 예약할 수 있습니다. ':''}반복 예약도 각 주의 한도를 적용합니다. 한 날짜라도 충돌하면 전체를 등록하지 않습니다.</div><div class="inline-error" id="booking-error" role="alert"></div><div class="modal-actions">${button('취소','close-modal')}<button class="btn primary" type="submit">예약하기</button></div></form>`,'',true);updateBookingPreview(date)}
function readPost(id){const p=S.posts.find(p=>String(p.id)===String(id));if(!p)return;S.viewPost=p;$('#main').innerHTML=`${button('목록으로','post-list','ghost','arrow-left')}<article class="article ${p.hasDocument?'document-article':''}" style="margin-top:20px"><span class="tag ${p.pinned?'orange':''}">${esc(p.category||'일반')}</span><h1>${esc(p.title)}</h1><div class="article-meta">${esc(p.authorName)} · ${postDate(p.updatedAt||p.createdAt)}</div>${p.sourceUrl?`<a class="btn source-link" href="${esc(p.sourceUrl)}" target="_blank" rel="noopener noreferrer">${icon('external-link')}노션·원문 페이지 열기</a>`:''}${p.hasDocument?`<iframe class="wiki-document" src="/api/posts/${p.id}/document" title="${esc(p.title)}" sandbox="allow-same-origin allow-popups allow-popups-to-escape-sandbox"></iframe>`:`<div class="body">${linkedText(p.body)}</div>`}${p.attachments?.length?`<div class="attachments"><h3>첨부파일</h3>${p.attachments.map(a=>`<a href="/api/attachments/${a.id}" download class="attachment">${icon('paperclip')}<span>${esc(a.name)}<small>${Math.ceil(a.size/1024)} KB</small></span>${icon('download')}</a>`).join('')}</div>`:''}${S.me.admin?button('수정','edit-post','','pencil'):''}</article>`;icons()}
function postModal(post=null){S.viewPost=post;showModal(post?'내용 수정':S.route==='wiki'?'위키 문서 작성':'공지 작성',`<form id="post-form" data-id="${post?.id||''}"><div class="form-grid">${field('제목','title','required maxlength="150"',post?.title||'',true)}${field('분류','category','maxlength="40" placeholder="예: 운영 안내, 공연, 장비"',post?.category||'',true)}${S.route==='wiki'?field('노션·원문 주소 (선택)','sourceUrl','type="url" placeholder="https://..."',post?.sourceUrl||'',true):''}<div class="field full"><label for="body">${post?.hasDocument?'문서 설명':'내용'}</label><textarea id="body" name="body" required maxlength="30000" placeholder="주소를 붙여 넣으면 클릭 가능한 링크로 표시됩니다.">${esc(post?.body||'')}</textarea></div><div class="field full"><label for="post-files">첨부파일 (파일당 10MB, 게시물당 5개)</label><input type="file" id="post-files" multiple accept=".pdf,.png,.jpg,.jpeg,.webp,.gif,.txt,.csv,.xlsx,.xls,.docx,.pptx,.zip"><small>현재 첨부 ${post?.attachments?.length||0}개 · PDF, 이미지, 문서, 엑셀, ZIP</small></div></div><label class="check-field"><input type="checkbox" name="pinned" ${post?.pinned?'checked':''}>상단에 고정하기</label><div class="inline-error" id="post-error" role="alert"></div><div class="modal-actions">${button('취소','close-modal')}<button class="btn primary" type="submit">${post?'변경 내용 저장':'등록하기'}</button></div></form>`,'',true)}
function notionModal(){S.notionFile=null;showModal('노션 페이지 가져오기',`<div class="info-strip">노션에서 ··· → 내보내기 → HTML → 파일과 이미지 포함으로 내려받은 ZIP을 올려 주세요. HTML 단일 파일도 가능합니다.</div><div class="field" style="margin-top:20px"><label for="notion-file">HTML 또는 ZIP 파일 (최대 20MB)</label><input id="notion-file" type="file" accept=".html,.htm,.zip"></div><div id="notion-page-selector"></div><p class="notion-note">가져온 시점의 본문·표·이미지를 보관합니다. 댓글, 편집 기능, 실시간 동기화는 포함되지 않습니다.</p><div class="inline-error" id="notion-error" role="alert"></div>`,`<div class="modal-actions">${button('취소','close-modal')}${button('가져오기','import-notion','primary','upload')}</div>`,true)}
async function importNotion(el){const f=S.notionFile;if(!f)throw new Error('HTML 또는 ZIP 파일을 선택해 주세요.');if(f.size>20*1024*1024)throw new Error('20MB 이하의 파일을 선택해 주세요.');el.disabled=true;try{const r=await api('/wiki/import',{method:'POST',body:await f.arrayBuffer(),raw:true,headers:{'Content-Type':'application/octet-stream','X-Entry':encodeURIComponent($('#notion-page')?.value||'')}});if(r.pages){$('#notion-page-selector').innerHTML=select('가져올 페이지 선택','notion-page',r.pages.map(p=>[p,p]),r.pages[0],true);return}closeModal();await navigate();readPost(r.id);toast('노션 문서를 가져왔습니다.')}catch(e){$('#notion-error').textContent=e.message}finally{el.disabled=false}}
function renderGuide(){ $('#main').innerHTML=pageHead('ADMIN HANDBOOK','무붕 운영진 사용 설명서','처음 맡는 운영도, 다음 기수로의 인수인계도 차근차근.')+`<div class="handbook">${S.guideSections.map((s,i)=>`<section class="panel handbook-section"><span class="chapter">${String(i+1).padStart(2,'0')}</span><div><h2>${esc(s.title.slice(5))}</h2><p>${linkedText(s.body)}</p></div></section>`).join('')}</div>`;icons()}
function renderSettings(){const s=S.settings;$('#main').innerHTML=pageHead('ROOM POLICY','합주실 예약 규칙','운영 시간은 08:00–24:00입니다. 한도와 취소·반복 예약 규칙을 설정하세요.')+`<section class="panel"><form class="panel-body" id="settings-form"><div class="section-title"><h2>기본 예약 규칙</h2></div><div class="settings-grid">${field('1주당 최대 개인 연습 시간','personalWeeklyHours','type="number" min="0.5" max="40" step="0.5" required',s.personalWeeklyHours)}${field('1주당 최대 팀 연습 시간','teamWeeklyHours','type="number" min="0.5" max="40" step="0.5" required',s.teamWeeklyHours)}${field('연속 예약 가능 시간','maxContinuousHours','type="number" min="0.5" max="16" step="0.5" required',s.maxContinuousHours)}${field('예약 가능한 기간 (주)','advanceWeeks','type="number" min="1" max="52" step="1" required',s.advanceWeeks)}${field('팀 정기예약 마감일 (선택)','recurringUntil','type="date"',s.recurringUntil)}</div><label class="check-field policy-toggle"><input type="checkbox" name="blockSameDayCancellation" ${s.blockSameDayCancellation?'checked':''}><span><strong>일반 부원의 당일 취소 제한</strong><small>켜면 한국 시간 기준 예약 당일에는 운영진만 취소할 수 있습니다.</small></span></label><div class="info-strip">${icon('info')}새 예약부터 한도·마감일을 적용합니다. 당일 취소 정책은 기존 예약에도 적용됩니다.</div><div class="inline-error" id="settings-error" role="alert"></div><div class="review-actions"><button class="btn primary" type="submit">설정 저장</button></div></form></section>`;icons()}

document.addEventListener('click',async e=>{
  const booking=e.target.closest('[data-booking]');if(booking){bookingDetail(booking.dataset.booking);return}
  const el=e.target.closest('[data-action]');if(!el)return;const a=el.dataset.action;
  try{
    if(a==='reload-page')location.reload();
    else if(a==='toggle-nav')$('.sidebar').classList.toggle('open');
    else if(a==='logout'){el.disabled=true;el.textContent='로그아웃 중…';S.request++;try{await api('/logout',{method:'POST'});S.me=null;S.upload=null;S.members=[];S.teams=[];S.bookings=[];S.posts=[];S.bookingData=null;S.settings=null;S.guideSections=[];closeModal();authScreen();toast('로그아웃했습니다.')}finally{el.disabled=false;if(el.isConnected)el.textContent='로그아웃'}}
    else if(a==='close-modal')closeModal();
    else if(a==='reload')navigate();
    else if(['members-tab','teams-tab','import-tab'].includes(a)){S.tab=a.split('-')[0];renderMembers()}
    else if(a==='member-password')memberPasswordModal(el.dataset.id);
    else if(a==='toggle-temp-password'){const input=$('#newPassword');input.type=input.type==='password'?'text':'password';el.textContent=input.type==='password'?'보기':'숨기기'}
    else if(a==='generate-temp-password'){$('#newPassword').value=temporaryPassword()}
    else if(a==='copy-temp-password'){try{await navigator.clipboard.writeText($('#newPassword').value);toast('임시 비밀번호를 복사했습니다.')}catch{$('#newPassword').type='text';$('#newPassword').select();toast('비밀번호를 선택했습니다. 직접 복사해 주세요.')}}
    else if(a==='reset-upload'){S.upload=null;S.summary=null;renderMembers()}
    else if(a==='commit-upload'){
      el.disabled=true;el.textContent='등록 중…';const result=await api('/import/commit',{method:'POST',body:{token:S.upload.token}});S.summary=result.summary||result;S.upload=null;
      if(result.reauthenticate){S.me=null;authScreen();toast('비밀번호가 변경되었습니다. 다시 로그인해 주세요.');return}
      const [m,t]=await Promise.all([api('/members'),api('/teams')]);S.members=m.members;S.teams=t.teams;if(S.route==='members')renderMembers();toast('멤버·팀과 소속 정보가 저장되었습니다.');
    }
    else if(['prev-week','next-week','today-week'].includes(a)){S.week=a==='today-week'?sunday(today()):addDays(S.week,a==='prev-week'?-7:7);await navigate()}
    else if(a==='zoom-calendar'){const zoom=$('#main-calendar').classList.toggle('zoom');el.textContent=zoom?'주간 전체 보기':'넓게 보기'}
    else if(a==='new-booking')await bookingModal(S.week>today()?S.week:today());
    else if(a==='export-members')await downloadMembers(el);
    else if(a==='new-event')eventModal();
    else if(a==='edit-event')eventModal(S.bookings.find(x=>String(x.id)===el.dataset.id));
    else if(a==='delete-event')showModal('일정을 삭제할까요?','<p>이 일정이 차지하던 시간이 다시 예약 가능한 시간으로 바뀝니다.</p>',`<div class="modal-actions">${button('돌아가기','close-modal')}<button class="btn danger" data-action="confirm-delete-event" data-id="${el.dataset.id}">일정 삭제</button></div>`);
    else if(a==='confirm-delete-event'){el.disabled=true;try{await api('/events/'+el.dataset.id,{method:'DELETE'});closeModal();await navigate();toast('일정을 삭제했습니다.')}finally{el.disabled=false}}
    else if(a==='calendar-slot')await bookingModal(el.dataset.date,el.dataset.time);
    else if(a==='pick-preview-slot'){
      ($('#event-date')||$('#date')).value=el.dataset.date;if($('#repeatUntil'))$('#repeatUntil').min=el.dataset.date;$('#start').value=el.dataset.time;const m=Math.min(1440,minutes(el.dataset.time)+60);$('#end').value=String(Math.floor(m/60)).padStart(2,'0')+':'+String(m%60).padStart(2,'0');toast(`${fmt(el.dataset.date)} ${el.dataset.time} 선택`);
    }
    else if(a==='cancel-booking')showModal('예약을 취소할까요?','<p>선택한 날짜의 예약을 취소합니다. 정기예약의 다른 날짜는 유지됩니다.</p>',`<div class="modal-actions">${button('돌아가기','close-modal')}<button class="btn danger" data-action="confirm-cancel" data-id="${el.dataset.id}">예약 취소</button></div>`);
    else if(a==='cancel-series'){
      el.disabled=true;try{
        const series=await api('/bookings/'+el.dataset.id+'/series');
        showModal('반복 예약 전체를 취소할까요?',`<p><strong>${esc(series.bookings[0]?.teamName)}</strong>의 같은 반복 묶음 <strong>${series.count}건</strong>을 모두 취소합니다. 이미 지난 날짜도 아래 목록에 있으면 포함됩니다.</p><div class="series-cancel-list"><ul>${series.bookings.map(b=>`<li>${esc(b.date)} · ${esc(b.start)}–${esc(b.end)}</li>`).join('')}</ul></div>${series.canCancelAll?'':`<div class="inline-error" role="alert">취소할 수 없는 날짜가 포함되어 있습니다. 운영진에게 문의해 주세요.</div>`}`,`<div class="modal-actions">${button('돌아가기','close-modal')}${series.canCancelAll?`<button class="btn danger" data-action="confirm-cancel-series" data-id="${el.dataset.id}">${series.count}건 전체 취소</button>`:''}</div>`);
      }finally{el.disabled=false}
    }
    else if(a==='confirm-cancel-series'){
      el.disabled=true;try{const result=await api('/bookings/'+el.dataset.id+'/series',{method:'DELETE'});closeModal();await navigate();toast(`반복 예약 ${result.count}건을 취소했습니다.`)}finally{el.disabled=false}
    }
    else if(a==='confirm-cancel'){await api('/bookings/'+el.dataset.id,{method:'DELETE'});closeModal();await navigate();toast('예약을 취소했습니다.')}
    else if(a==='new-post')postModal();else if(a==='read-post')readPost(el.dataset.id);else if(a==='post-list')renderPosts();else if(a==='edit-post')postModal(S.viewPost);
    else if(a==='notion-import')notionModal();else if(a==='import-notion')await importNotion(el);
  }catch(err){toast(err.message);if(a==='commit-upload'&&S.me&&S.route==='members')renderMembers()}
});
document.addEventListener('change',e=>{
  if(e.target.id==='xlsx-file'&&e.target.files[0])uploadFile(e.target.files[0]);
  if(e.target.id==='member-sort'){S.memberSort=e.target.value;refreshMemberTable()}
  if(e.target.id==='member-order'){S.memberOrder=e.target.value;refreshMemberTable()}
  if(e.target.id==='notion-file'){S.notionFile=e.target.files[0];$('#notion-page-selector').innerHTML=''}
  if(e.target.id==='date'&&e.target.value){updateBookingPreview(e.target.value);$('#repeatUntil').min=e.target.value}
  if(e.target.id==='event-date'&&e.target.value)updateBookingPreview(e.target.value);
  if(e.target.id==='type'&&$('#team-field')){
    const team=e.target.value==='team';$('#team-field').hidden=!team;$('#teamId').required=team;
    if($('#booking-member-field')){$('#booking-member-field').hidden=team;$('#bookingMemberId').disabled=team;$('#bookingMemberId').required=!team}
    if(!team){$('#repeat-weekly').checked=false;$('#repeat-end-field').hidden=true;$('#repeatUntil').disabled=true;$('#repeatUntil').required=false}
  }
  if(e.target.id==='repeat-weekly'){const yes=e.target.checked;$('#repeat-end-field').hidden=!yes;$('#repeatUntil').disabled=!yes;$('#repeatUntil').required=yes}
});
document.addEventListener('input',e=>{if(e.target.id==='member-search')refreshMemberTable();if(e.target.id==='post-search'){const q=e.target.value.toLowerCase();$('#post-list').innerHTML=postCards(S.posts.filter(p=>(p.title+' '+p.body).toLowerCase().includes(q)));icons()}});
document.addEventListener('submit',async e=>{
  e.preventDefault();const f=e.target,b=$('[type=submit]',f),data=Object.fromEntries(new FormData(f));if(!b)return;b.disabled=true;const form=f.getAttribute('id');
  try{
    if(form==='auth-form'){const r=await api(f.dataset.setup==='true'?'/setup':'/login',{method:'POST',body:data});S.me=r.member;await navigate();if(S.me.mustChangePassword)passwordScreen()}
    else if(form==='password-form'){if(data.newPassword!==data.confirmPassword)throw new Error('새 비밀번호가 서로 다릅니다.');S.me=(await api('/password',{method:'POST',body:data})).member;closeModal();await navigate();toast('새 비밀번호를 저장했습니다.')}
    else if(form==='member-password-form'){
      await api('/members/password-reset',{method:'POST',body:{...data,memberId:f.dataset.id}});
      const member=S.members.find(m=>m.id===f.dataset.id);if(member)member.mustChangePassword=true;
      const targetId=f.dataset.id,targetName=member?.name||targetId;
      showModal('임시 비밀번호를 저장했습니다',`<p><strong>${esc(targetName)}</strong> · ${esc(targetId)}</p><p class="password-help">아래 비밀번호를 해당 멤버에게 전달해 주세요. 이 창을 닫으면 다시 조회할 수 없습니다.</p>${field('저장한 임시 비밀번호','newPassword','type="password" readonly autocomplete="off"',data.newPassword)}<div class="password-tools">${button('보기','toggle-temp-password','small','eye')}${button('복사','copy-temp-password','small','copy')}</div><div class="modal-actions">${button('완료','close-modal','primary')}</div>`);
      if(S.route==='members')renderMembers();
    }
    else if(form==='booking-form'){
      if(data.type==='team')data.teamId=Number(data.teamId);else{delete data.teamId;delete data.repeatUntil}
      const r=await api('/bookings',{method:'POST',body:data});closeModal();S.week=sunday(data.date);await navigate();toast(r.count>1?`${r.count}회의 정기예약을 등록했습니다.`:'예약이 완료되었습니다.');
    }
    else if(form==='event-form'){
      data.date=data['event-date'];delete data['event-date'];
      await api('/events'+(f.dataset.id?'/'+f.dataset.id:''),{method:f.dataset.id?'PUT':'POST',body:data});closeModal();S.week=sunday(data.date);await navigate();toast(f.dataset.id?'일정을 수정했습니다.':'일정을 등록했습니다.');
    }
    else if(form==='post-form'){
      const files=[...$('#post-files').files];if(files.some(x=>x.size>10*1024*1024))throw new Error('첨부파일은 각각 10MB 이하로 선택해 주세요.');if(files.length+(S.viewPost?.attachments?.length||0)>5)throw new Error('게시물당 파일은 최대 5개입니다.');
      data.kind=S.route;data.pinned=f.pinned.checked;const saved=await api('/posts'+(f.dataset.id?'/'+f.dataset.id:''),{method:f.dataset.id?'PUT':'POST',body:data});f.dataset.id=saved.post.id;f._uploadedFiles??=new Set();
      for(const file of files){const key=file.name+':'+file.size+':'+file.lastModified;if(f._uploadedFiles.has(key))continue;try{await api('/posts/'+saved.post.id+'/attachments',{method:'POST',raw:true,body:await file.arrayBuffer(),headers:{'Content-Type':'application/octet-stream','X-Filename':encodeURIComponent(file.name)}});f._uploadedFiles.add(key)}catch(err){throw new Error('본문은 저장되었습니다. 첨부 실패: '+err.message)}}
      closeModal();await navigate();toast('저장되었습니다.');
    }
    else if(form==='settings-form'){
      for(const k of ['personalWeeklyHours','teamWeeklyHours','maxContinuousHours','advanceWeeks'])data[k]=Number(data[k]);
      data.blockSameDayCancellation=f.blockSameDayCancellation.checked;await api('/settings',{method:'PUT',body:data});toast('예약 규칙을 저장했습니다.');
    }
  }catch(err){const target=$('.inline-error',f);if(target)target.textContent=err.message;else toast(err.message)}finally{b.disabled=false}
});
